  "app.safety.title": "安全",
  "app.safety.subtitle": "工伤和险情。险情和工伤一样值得上报——这样才能在有人受伤之前学到教训。",
  "app.safety.reportButton": "上报",
  "app.safety.kind.near_miss": "险情",
  "app.safety.kind.injury": "工伤",
  "app.safety.kind.property_damage": "财物损坏",
  "app.safety.kind.other": "其他",
